import React, { useState } from 'react'
import styled from 'styled-components'
import { dateFormat } from '../../utils/dateFormat';
import { Land,Machine,Investor,bitcoin, book, calender, card, circle, clothing, comment, dollar, food, freelance, medical, money, piggy, stocks, takeaway, trash, tv, users, yt, edit } from '../../utils/Icons';
import Button from '../Button/Button';

function IncomeItem({
    id,
    title,
    amount,
    date,
    category,
    description,
    deleteItem,
    updateItem,
    indicatorColor,
    type
}) {

    const categoryIcon = () =>{
        switch(category) {
            case 'Investor':
                return Investor;
            case 'Machine':
                return Machine;
            case 'HR':
                return users;
            case 'Land':
                return Land;
            case 'Other':
                return book;
            default:
                return ''
        }
    }

    const expenseCatIcon = () => {
        switch (category) {
            case 'education':
                return book;
            case 'groceries':
                return food;
            case 'health':
                return medical;
            case 'subscriptions':
                return tv;
            case 'takeaways':
                return takeaway;
            case 'clothing':
                return clothing;
            case 'travelling':
                return freelance;
            case 'other':
                return circle;
            default:
                return ''
        }
    }

    const [isPopupOpen, setIsPopupOpen] = useState(false);
    const [updatedIncome, setUpdatedIncome] = useState({
        title,
        amount,
        category,
        description,
        date,
    });

    const handleUpdateClick = () => {
        setIsPopupOpen(true);
    };

    const handleClosePopup = () => {
        setIsPopupOpen(false);
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setUpdatedIncome({ ...updatedIncome, [name]: value });
    };

    const handleUpdateSubmit = () => {
        updateItem(id, updatedIncome);
        setIsPopupOpen(false);
    };

    console.log('type', type)

    return (
        <IncomeItemStyled indicator={indicatorColor}>
            {/* Icon */}
            <div className="icon">
    {type === 'expense' ? expenseCatIcon() : categoryIcon()}
</div>

<div className="content">
    {/* Title */}
    <div className="row">
        <div className="column">
            <p><strong>Income Title : </strong> {title}</p>
        </div>
        <div className="column">
            <p><strong>Income Amount : </strong>LKR {amount}</p>
        </div>
        <div className="column">
            <div className="btn-group">
                <Button 
                    icon={edit}
                    bPad={'1rem'}
                    bRad={'50%'}
                    bg={'var(--primary-color)'}
                    color={'#fff'}
                    iColor={'#fff'}
                    hColor={'var(--color-green)'}
                    onClick={handleUpdateClick}
                />
                <Button 
                    icon={trash}
                    bPad={'1rem'}
                    bRad={'50%'}
                    bg="#990000"
                    color={'#fff'}
                    iColor={'#fff'}
                    hColor={'var(--color-green)'}
                    onClick={() => deleteItem(id)}
                />
            </div>
        </div>
    </div>

    {/* Transaction Date and Department */}
    <div className="row">
        <div className="column">
            <p><strong>Date : </strong> {dateFormat(date)}</p>
        </div>
        <div className="column">
            <p><strong>Department : </strong>{category}</p>
        </div>
        <div className="column">
            {/* Empty column for spacing */}
        </div>
    </div>

    {/* Description */}
    <p className="description">
        <strong>Description : </strong>
        {description}
    </p>
</div>




            {/* Update Popup */}
            {/* {isPopupOpen && (
                <PopupStyled>
                    <div className="popup">
                        <h3>Update Income</h3>
                        <input type="text" name="title" value={updatedIncome.title} onChange={handleInputChange} placeholder="Title" />
                        <input type="number" name="amount" value={updatedIncome.amount} onChange={handleInputChange} placeholder="Amount" />
                        <select required value={updatedIncome.category} name="category" id="category" onChange={handleInputChange} placeholder="Category">
                        <option value="" disabled>Department</option>
                            <option value="Investor">Investor Department</option>
                            <option value="Machine">Machine Department</option>
                            <option value="Land">Land Department</option>
                            <option value="HR">HR Department</option> 
